import{_ as e,o as t,c as o,a3 as s}from"./chunks/framework.DeRSg1wr.js";const _=JSON.parse('{"title":"TLog能解决什么痛点","description":"用同一个 traceId 关联分布式请求的已有日志，了解 TLog 的作用和边界。","frontmatter":{"title":"TLog能解决什么痛点","date":"2022-09-12T13:22:16.000Z","permalink":"/pages/5b7bd2/","description":"用同一个 traceId 关联分布式请求的已有日志，了解 TLog 的作用和边界。"},"headers":[],"relativePath":"pages/5b7bd2/index.md","filePath":"10.文档/010.TLog能解决什么痛点.md"}'),r={name:"pages/5b7bd2/index.md"};function p(n,a,i,d,l,c){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="tlog能解决什么痛点" tabindex="-1">TLog能解决什么痛点 <a class="header-anchor" href="#tlog能解决什么痛点" aria-label="Permalink to &quot;TLog能解决什么痛点&quot;">​</a></h1><p>一次请求经过多个服务时，应用日志往往分散在不同文件或日志平台中。TLog 在入口建立 traceId，在适配的 HTTP、RPC、消息（Kafka、RabbitMQ 等）和任务调用中传递上下文，让同一条链路的日志可以用同一个 ID 检索。</p><p>例如，订单服务调用库存服务时，两边可以输出：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;0&gt;&lt;demo-request-001&gt; 开始处理订单</span></span>
<span class="line"><span>&lt;0.1&gt;&lt;demo-request-001&gt; 检查库存</span></span></code></pre></div><p>其中 traceId 关联请求，spanId 表示调用层级。TLog 还可以把上游应用、主机、IP 和方法级业务标签放入日志。</p><h2 id="与现有日志平台配合" tabindex="-1">与现有日志平台配合 <a class="header-anchor" href="#与现有日志平台配合" aria-label="Permalink to &quot;与现有日志平台配合&quot;">​</a></h2><p>TLog 不负责采集、存储、检索或展示日志。它把标签写入已有日志；日志文件、集中采集系统或云日志服务继续承担后续处理。接入后应同时检查应用实际输出和日志平台的字段提取规则。</p><p>已有 OpenTelemetry 或其它追踪系统的项目也可使用 TLog。2.0 可以从合法的 W3C <code>traceparent</code> 入站头复用 traceId，方便关联检索；它不提供完整的 W3C 出站传播、采样决策或 span 导出。</p><h2 id="从哪里开始" tabindex="-1">从哪里开始 <a class="header-anchor" href="#从哪里开始" aria-label="Permalink to &quot;从哪里开始&quot;">​</a></h2><p>Spring Boot 项目先看<a href="/guide/quick-start/">快速开始</a>，已有 1.x 项目先看<a href="/guide/upgrade/">升级指南</a>。TLog 2.0 仅通过日志配置文件接入，原来的 javaagent 和字节码增强方式已移除。</p><p>性能取决于日志量、线程模型和上下文传播路径。当前文档不承诺固定损耗比例；实际验证范围见<a href="/guide/compatibility/">兼容性与验收</a>。</p>`,11)])])}const h=e(r,[["render",p]]);export{_ as __pageData,h as default};
